INSERT INTO entities (id, slug, kind, name, summary, description, organization, country, lifecycle, visibility, openness_status, license_spdx, canonical_url, repository_url, documentation_url, first_seen_at, last_seen_at, last_verified_at, created_at, updated_at, hero_image_url, image_source, image_source_url, image_usage_note) VALUES ('robotics_microduck', 'microduck', 'robot', 'Microduck', 'A 25 cm biped from Pollen Robotics for play and robot learning, with open software and non-open hardware.', 'Microduck is a small physical robot with a grasping beak and learned motion skills. Its software connects simulation training to onboard ONNX execution. The manufacturer explicitly excludes mechanical and electronic design files from its open-source claim. Pre-production specifications and delivery targets may change.', 'Pollen Robotics', 'FR', 'active', 'public', 'unknown', NULL, 'https://pollen-robotics.com/microduck/', 'https://github.com/pollen-robotics/microduck', 'https://pollen-robotics.com/microduck/press-kit/', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z', 'https://pollen-robotics.com/assets/microduck/gallery/closeup.webp', 'Pollen Robotics press photography', 'https://pollen-robotics.com/microduck/press-kit/', 'Official launch photograph; editorial product identification. Credit: Pollen Robotics.');
INSERT INTO entity_domains (entity_id, domain, is_primary, confidence, classification_method, review_status, source_url, created_at, updated_at) VALUES ('robotics_microduck', 'robotics', 1, 1, 'source', 'verified', 'https://pollen-robotics.com/microduck/press-kit/', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z');
INSERT INTO robotics_profiles (entity_id, layer, form_factor, stack_type, model_type, metadata_json, confidence, classification_method, review_status, source_url, created_at, updated_at) VALUES ('robotics_microduck', 'platform', 'biped', NULL, NULL, '{"robot_type":"Biped","dof":15,"height":"25 cm","width":"14 cm","weight":"Under 800 g (official press kit)","actuators":"15 motors; 14 policy outputs plus grasping beak control","sensors":"Front camera; 8×8 ToF range sensor; head and body IMUs; microphones; two NFC antennas","end_effector":"Articulated grasping beak","compute":"Rockchip RK3566 with AI accelerator; 1 GB RAM; 32 GB storage","battery":"Removable NP-F550, 2600 mAh; approximately one hour, depending on use","teleoperation":"Included game controller; robotctl and Bluetooth duckctl","configuration":"Cream, Graphite, Lavender and Sky are colourways of the same platform","hardware_openness":"Not open hardware","software_openness":"Apache-2.0 software","availability":"Pre-order; delivery target before Christmas 2026","simulation":["MuJoCo","MuJoCo Warp"],"software_ecosystem":["Microduck runtime","Microduck RL","ONNX"],"specification_note":"Official pre-production specifications; camera, LiDAR and radio details remain provisional."}', 1, 'source', 'verified', 'https://pollen-robotics.com/microduck/press-kit/', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z');
