INSERT INTO entities (id, slug, kind, name, summary, description, organization, country, lifecycle, visibility, openness_status, license_spdx, canonical_url, repository_url, documentation_url, first_seen_at, last_seen_at, last_verified_at, created_at, updated_at) VALUES ('robotics_microduck_runtime', 'microduck-runtime', 'tool', 'Microduck Runtime', 'The Rust control software, device services and update system running on Microduck.', 'This is the software in pollen-robotics/microduck, not another physical robot. It runs the onboard control loop, loads neural policies and exposes control interfaces. GitHub stars and activity belong to this repository record and are not duplicated on the robot or its policy collection.', 'Pollen Robotics', 'FR', 'active', 'public', 'open-source', 'Apache-2.0', 'https://github.com/pollen-robotics/microduck', 'https://github.com/pollen-robotics/microduck', 'https://github.com/pollen-robotics/microduck/tree/main/docs', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z');
