INSERT INTO entities (id, slug, kind, name, summary, description, organization, country, lifecycle, visibility, openness_status, license_spdx, canonical_url, repository_url, documentation_url, first_seen_at, last_seen_at, last_verified_at, created_at, updated_at) VALUES ('robotics_microduck_rl', 'microduck-rl', 'robotics-framework', 'Microduck RL', 'MuJoCo Warp / mjlab training environments and PPO workflows for Microduck motion policies.', 'Microduck RL provides simulation tasks, actuator modelling, domain randomization and export tools for training policies that run on the physical Microduck. Training uses a CUDA GPU locally or through Hugging Face Jobs. Code is Apache-2.0; the README separately places 3D model files under non-commercial Creative Commons terms.', 'Pollen Robotics', 'FR', 'active', 'public', 'open-source', 'Apache-2.0', 'https://github.com/pollen-robotics/microduck_rl', 'https://github.com/pollen-robotics/microduck_rl', 'https://github.com/pollen-robotics/microduck_rl/blob/d424a0c899f6b33cbd3daeb279913134349c0b63/README.md', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z');
