INSERT INTO entities (id, slug, kind, name, summary, description, organization, country, lifecycle, visibility, openness_status, license_spdx, canonical_url, repository_url, documentation_url, first_seen_at, last_seen_at, last_verified_at, created_at, updated_at) VALUES ('robotics_microduck_policies', 'microduck-policies', 'model', 'Microduck Policies', 'Nine published ONNX policy files for Microduck walking, recovery, ground pickup, kicks and rollers.', 'This collection indexes the ONNX files in the official runtime repository at a reviewed commit. Filenames describe deployment roles, not independent training-run versions. The website advertises seven shipped behaviours; the reviewed directory contains nine files. The planned move to Hugging Face model repositories is not yet treated as a released resource.', 'Pollen Robotics', 'FR', 'active', 'public', 'source-available', NULL, 'https://github.com/pollen-robotics/microduck/tree/main/policies', NULL, 'https://github.com/pollen-robotics/microduck/blob/590b986bd8c0d50ae02cb3ea2f59c463b6828168/policies/README.md', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z', '2026-08-28T00:15:31.783Z');
